"""MCP server generated by intpot."""


from pathlib import Path

from pydantic import Field as _intpot_mcp_field
from fastmcp import FastMCP as _intpot_mcp_fastmcp

DAILY_RATE = 0.02

CAPACITY_GB = 20000

def storage_cost(size_gb: int, days: int, replicas: int) -> float:
    if size_gb * replicas > CAPACITY_GB:
        raise ValueError('replicated storage exceeds capacity')
    return round(size_gb * days * replicas * DAILY_RATE, 2)

mcp = _intpot_mcp_fastmcp('storage_quote')
_intpot_required = object()


def _storage_quote_impl(
    size_gb: int = _intpot_required,
    days: int = 7,
    replicas: int = 2,
    receipt: str = '',
) -> dict:
    """Estimate storage cost within individual and replicated capacity limits."""
    if size_gb is _intpot_required:
        raise TypeError('Missing required argument: size_gb')
    cost = storage_cost(size_gb, days, replicas)
    result = {"cost": cost, "size_gb": size_gb, "days": days, "replicas": replicas}
    if receipt:
        Path(receipt).write_text(str(result), encoding="utf-8")
    return result


@mcp.tool(name='storage_quote')
def storage_quote(
    size_gb: int = _intpot_mcp_field(..., ge=1, le=10000),
    days: int = _intpot_mcp_field(7, ge=1, le=365),
    replicas: int = _intpot_mcp_field(2, ge=1, le=3),
    receipt: str = '',
) -> dict:
    """Estimate storage cost within individual and replicated capacity limits."""

    return _storage_quote_impl(size_gb, days, replicas, receipt)


if __name__ == "__main__":
    mcp.run()
